fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x * y)
     .collect()
}

fn main() {
    let v1 = vec![1, 2, 3, 4];
    let v2 = vec![5, 6, 7, 8];
    let result = product(&v1, &v2);
    println!("{:?}", result); // prints [5, 12, 21, 32]
}